function validate([n, edges, price]) {
  if (!Number.isInteger(n) || n < 1 || n > 100000) return 'n is between 1 and 10^5.';
  if (!Array.isArray(edges) || edges.length !== n - 1) return 'edges needs exactly n - 1 edges.';
  if (!Array.isArray(price) || price.length !== n) return 'price needs exactly n values.';
  if (price.some(p => !Number.isInteger(p) || p < 1 || p > 100000)) return 'Each price is between 1 and 10^5.';
  const root = Array.from({ length: n }, (_, i) => i);
  const find = x => {
    while (root[x] !== x) {
      root[x] = root[root[x]];
      x = root[x];
    }
    return x;
  };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [a, b].';
    const [a, b] = edge;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 0 || b < 0 || a >= n || b >= n) return 'Edge ends are nodes 0 to n - 1.';
    const ra = find(a), rb = find(b);
    if (ra === rb) return 'edges must form a tree (no loops or repeated edges).';
    root[ra] = rb;
  }
  return null;
}

