function maxOutput(n, edges, price) {
  const graph = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) {
    graph[a].push(b);
    graph[b].push(a);
  }
  // Root the tree at 0 and list the nodes so that every parent comes before its children.
  const parent = new Array(n).fill(-1);
  const order = [0];
  for (let i = 0; i < order.length; i++) {
    const node = order[i];
    for (const next of graph[node]) {
      if (next === parent[node]) continue;
      parent[next] = node;
      order.push(next);
    }
  }
  // withLeaf[v]: best downward path from v, counting every node on it.
  // withoutLeaf[v]: best downward path from v with the price of its last node left out.
  const withLeaf = price.slice();
  const withoutLeaf = new Array(n).fill(0);
  let best = 0;
  for (let i = n - 1; i > 0; i--) {
    const child = order[i];
    const node = parent[child];
    best = Math.max(best, withLeaf[node] + withoutLeaf[child], withoutLeaf[node] + withLeaf[child]);
    withLeaf[node] = Math.max(withLeaf[node], price[node] + withLeaf[child]);
    withoutLeaf[node] = Math.max(withoutLeaf[node], price[node] + withoutLeaf[child]);
  }
  return best;
}

