function maxOutput(n, edges, price) {
  const adj = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); }
  let answer = 0;
  for (let root = 0; root < n; root++) {
    // Price sums of the paths from root to every node, found with an explicit stack.
    const sums = [];
    const stack = [[root, -1, price[root]]];
    while (stack.length) {
      const [v, from, sum] = stack.pop();
      sums.push(sum);
      for (const u of adj[v]) if (u !== from) stack.push([u, v, sum + price[u]]);
    }
    answer = Math.max(answer, Math.max(...sums) - Math.min(...sums));
  }
  return answer;
}

