function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? pick(1800, 2000) : pick(1, 9);
  const shape = pick(0, 3);
  // Build a tree on 0..n-1 by attaching node i to an earlier node, then relabel it at random.
  const parentOf = i => {
    if (shape === 0) return i - 1;
    if (shape === 1) return 0;
    if (shape === 2) return Math.max(0, i - pick(1, 3));
    return pick(0, i - 1);
  };
  const label = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) {
    const j = pick(0, i);
    [label[i], label[j]] = [label[j], label[i]];
  }
  const edges = [];
  for (let i = 1; i < n; i++) {
    const a = label[i], b = label[parentOf(i)];
    edges.push(rand() < 0.5 ? [a, b] : [b, a]);
  }
  for (let i = edges.length - 1; i > 0; i--) {
    const j = pick(0, i);
    [edges[i], edges[j]] = [edges[j], edges[i]];
  }
  const top = rand() < 0.3 ? pick(1, 3) : large || rand() < 0.5 ? 100000 : 20;
  const price = Array.from({ length: n }, () => pick(1, top));
  return [n, edges, price];
}
